class Order(                       // aggregate root
    @Id val id: Long,
    @Version var version: Int = 0,
    @OneToMany(mappedBy = "order", cascade = [CascadeType.ALL])
    var lines: MutableList<OrderLine> = mutableListOf()
)

@Transactional
fun apply(id: Long, delta: Int) {
    val root = em.find(Order::class.java, id)
    root.lines.first().qty += delta   // one token for the cluster
}

private val locks = ConcurrentHashMap<Long, Mutex>()

suspend fun <T> withCluster(id: Long, block: suspend () -> T): T =
    locks.computeIfAbsent(id) { Mutex() }.withLock { block() }

suspend fun apply(id: Long, delta: Int) = withCluster(id) {
    val root = clusters.getValue(id)   // root + members, one lock
    root.lines.first().qty += delta
}

